{"policy":"permit (
    principal is User,
    action == Action::"sendCommand",
    resource is Command
)
when {
    principal.roles.containsAny([
        Role::"operator",
        Role::"technician",
        Role::"fleetAdmin"
    ])
};

forbid (
    principal is User,
    action == Action::"sendCommand",
    resource is Command
)
when {
    principal.roles.containsAny([
        Role::"operator",
        Role::"technician",
        Role::"fleetAdmin"
    ]) &&
    (!context.maintenanceWindow.permitted ||
     context.currentTime < context.maintenanceWindow.startTime ||
     context.currentTime > context.maintenanceWindow.endTime)
};

forbid (
    principal is User,
    action == Action::"sendCommand",
    resource is Command
)
when {
    principal.roles.containsAny([
        Role::"operator",
        Role::"technician",
        Role::"fleetAdmin"
    ]) &&
    principal != resource.targetDevice.owner &&
    (resource.targetDevice.status == DeviceStatus::"provisioned" ||
     resource.targetDevice.status == DeviceStatus::"decommissioned")
};"}
